Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      if Z.eqb pc PC_SM then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_SM && Nat.eqb i 0 && Nat.eqb j 1 && CBA.regions_eqb (CC.cp_F c) CPF0
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 512 1 (nth i G.BLS []) (nth i FFS []) [] (List.filter (sm_ok ps i) (CC.cp_know cj)) None c ps cj
                                             (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => (Nat.eqb (CH2.ci_nx ci) 48 && Z.eqb (CH2.ci_csp ci) (-128))%bool | None => false end)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_VPUSH then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_VPUSH && Nat.eqb i 1 && Nat.eqb j 2 && Nat.ltb 53 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8240 2 [] (nth i FFS []) VEC_W NEWS_V None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => (Z.eqb (CH2.ci_csp ci) (-128) && Nat.eqb (CH2.ci_nx ci) 65)%bool | None => false end
                                  && CL.ps_reg_is ps 10 (EAlu Instr.ALU_ADD PE (ELit 248)) && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD (EVar 2) (ELit (-89)))
                                  && has cells (KWord (SA (EVar 2) (-89)) 1 (ELit KIND)) && has cells (KWord (SA FE 56) 8 FLE) && CBA.has_range cells (EVar 34) 0 1023)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_VISIT then      (* [comment removed for export] *)
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_VISIT && Nat.eqb i 2 && Nat.eqb j 4 && Nat.ltb 66 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && CHA.frames_eqb (nth j FFS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI XKA.VIS 0 (nth i G.BLS []) (nth i FFS []) WENC NEWS_F (Some (ELit 1)) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-128) | None => false end
                                  && has cells (KWord (SA FE 56) 8 FLE) && CL.ps_reg_is ps 10 VE
                                  && has cells (KZero (SA (CHA.SRL3 VE) SBz) (ELit 51)) && has cells (KZero (SA (CHA.SRL3 S2E) SBz) (ELit 3))
                                  && CBA.has_range cells (EVar 34) 0 1023)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_ERRH then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_ERRH && Nat.eqb i 1 && Nat.eqb j 3 && Nat.ltb 53 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CC.has_cell (CC.cp_know c) KZF
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 16 0 (nth i G.BLS []) (nth i FFS []) [] NEWS_F (Some (ELit 0)) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-128) | None => false end
                                  && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD FE (ELit 32))
                                  && has cells (KWord (SA FE 32) 4 (ELit ERRC)) && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 4)) 1 (ELit 4)) && has cells (KWord (SA FE 56) 8 FLE)
                                  && CBA.has_range cells (EVar 34) 1024 1024)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_SETEC then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_SETEC && Nat.eqb i 3 && Nat.eqb j 5 && Nat.ltb 66 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 1024 0 (nth i G.BLS []) (nth i FFS []) SETEC_W NEWS_F None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-128) | None => false end
                                  && CL.ps_reg_is ps 10 EE && CL.ps_reg_is ps 11 (ELit ERRC) && has cells (KWord (SA FE 56) 8 FLE))%bool
                    | None => false end
        | None => false end
      else
        (CBA.exit_base_chk GT.NF RETPC c ps && Nat.ltb 66 (CC.cp_nx c)
         && match CHA.retire_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS []) with Some fle => expr_eqb fle FLE | None => false end
         && has cells (KWord (SA FLE 0) 1 (ELit 0)) && CBA.regions_eqb (CC.cp_F c) CPF4
         && has cells (KWord (SA PE 144) 4 (EAlu Instr.ALU_ADD (EVar 34) (ELit 1)))
         && ((Nat.eqb i 4 && has cells (KWord (SA PE 208) 1 (ELit STNEW)) && has cells (KWord (SA PE 211) 1 (ELit 1)) && CBA.has_range cells (EVar 34) 0 1023)
             || (Nat.eqb i 5 && has cells (KWord (SA PE 208) 1 (EVar 35)) && has cells (KWord (SA PE 211) 1 (ELit 0)) && CBA.has_range cells (EVar 34) 1024 1024)))%bool
  end.
