Lemma crd_grow : forall bcap kx bx cr c, CRD bcap kx bx cr c -> In c [66; 132; 264; 528] ->
  acredit_ok L cr (2 * c) /\ CRD bcap kx bx (adebit L cr (2 * c)) (2 * c).
